// Map the FinFlow approval payload into an ERP accounts-payable voucher.
// Voucher number is derived from the FinFlow invoice id and approval date, so a retried webhook
// produces the same voucher number instead of a duplicate posting.
return $input.all().map((item) => {
  const p = item.json.body ?? item.json;
  const postedAt = new Date().toISOString();
  const approvedDate = String(p.approved_at || postedAt).slice(0, 10).replace(/-/g, '');
  const voucherNumber = `APV-${approvedDate}-${String(p.invoice_id).slice(0, 8).toUpperCase()}`;

  return {
    json: {
      voucher_type: 'AP_INVOICE',
      voucher_number: voucherNumber,
      vendor: { id: p.vendor?.id, name: p.vendor?.name },
      invoice_number: p.invoice_number,
      invoice_date: p.invoice_date,
      due_date: p.due_date,
      currency: p.currency,
      total: Number(p.total),
      lines: (p.line_items || []).map((line, index) => ({
        line: index + 1,
        description: line.description,
        quantity: Number(line.quantity),
        unit_price: Number(line.unit_price),
        amount: Number(line.total),
      })),
      approved_by: p.approved_by?.email ?? p.approved_by?.role,
      source: { system: 'FinFlow', invoice_id: p.invoice_id },
      posted_at: postedAt,
    },
  };
});
